## Implementation Details

```rust
pub struct TransitionContext<'a> {
    pub trigger: TransitionTrigger,         // OperatorAction, DaemonAutomatic, SkillResult
    pub side_effect_reached: Option<SideEffectClass>,
    pub validator_verdict: Option<ValidatorVerdict>,
    pub override_metadata: Option<OperatorOverride>,
    pub readiness_basis: Option<&'a ReadinessOutcome>,
}

pub async fn transition_to(
    runtime: &DaemonRuntime,
    job: &WorkflowJob,
    bid_scope: &BidScopePayload,
    target: BidWorkflowState,
    ctx: TransitionContext<'_>,
) -> Result<(), BidStateTransitionError> {
    let current = runtime.db.load_bid_state(&bid_scope.process_id).await?;

    if !is_allowed(current, target) {
        return Err(BidStateTransitionError::IllegalTransition { from: current, to: target });
    }

    // RE-verify prerequisites before transition (no cached eligibility)
    match (current, target) {
        (BidWorkflowState::NotStarted, BidWorkflowState::ReadyToBid) => {
            // L6-FR-1.3.2: re-verify readiness
            let readiness = evaluate_bid_readiness(runtime, bid_scope).await?;
            if !readiness.eligible {
                return Err(BidStateTransitionError::ReadinessFailed(readiness));
            }
        }
        (BidWorkflowState::ReadyToBid, BidWorkflowState::BidInProgress) => {
            // L6-FR-1.3.3: prerequisites re-verified at this moment
            let readiness = evaluate_bid_readiness(runtime, bid_scope).await?;
            if !readiness.eligible {
                return Err(BidStateTransitionError::ReadinessFailed(readiness));
            }
        }
        (BidWorkflowState::BidInProgress, BidWorkflowState::BidFailed) => {
            // L6-FR-1.3.7: reject if REMOTE_DRAFT+ reached — should go to portal_state_unknown
            if let Some(se) = ctx.side_effect_reached {
                if se >= SideEffectClass::RemoteDraft {
                    return Err(BidStateTransitionError::ShouldBePortalStateUnknown);
                }
            }
        }
        (BidWorkflowState::BidInProgress, BidWorkflowState::BidSubmitted)
        | (BidWorkflowState::DraftSaved, BidWorkflowState::BidSubmitted) => {
            // L6-FR-1.3.6 / L6-FR-1.3.9: fail-closed validation + fresh decisionBasisHash
            let current_hash = decision_basis_hash::compute(runtime, bid_scope).await?;
            if current_hash != bid_scope.decision_basis_hash {
                return Err(BidStateTransitionError::DecisionBasisStale);
            }
            match ctx.validator_verdict {
                Some(ValidatorVerdict::Approved) => {},
                _ => {
                    if ctx.override_metadata.is_none() {
                        return Err(BidStateTransitionError::ValidationGateBlocked);
                    }
                }
            }
        }
        // ... 11 more transition arms ...
        _ => {}
    }

    // Atomic write: state, side-effect, validator verdict, override metadata
    runtime.db.write_bid_state_transition(bid_scope, target, &ctx).await?;
    Ok(())
}

fn is_allowed(from: BidWorkflowState, to: BidWorkflowState) -> bool {
    matches!((from, to),
        (BidWorkflowState::NotStarted, BidWorkflowState::ReadyToBid) |
        (BidWorkflowState::ReadyToBid, BidWorkflowState::BidInProgress) |
        (BidWorkflowState::ReadyToBid, BidWorkflowState::NotStarted) |
        // ... 11 more allowed pairs (14 total per §1.3) ...
    )
}
```

