pub async fn validate_bid_scope(
    runtime: &DaemonRuntime,
    scope: &BidScopePayload,
) -> Result<(), BidScopeValidationError> {
    // L6-FR-1.10.3: shape
    if scope.lot_ids.is_empty() { return Err(BidScopeValidationError::EmptyLotIds); }
    if scope.candidate_ids.is_empty() { return Err(BidScopeValidationError::EmptyCandidateIds); }
    if scope.selected_quote_ids.is_empty() { return Err(BidScopeValidationError::EmptySelectedQuoteIds); }
    if scope.portal_opportunity_ref.is_empty() { return Err(BidScopeValidationError::EmptyOpportunityRef); }
    if scope.decision_basis_hash.len() != 64 { return Err(BidScopeValidationError::DecisionBasisHashWrongLength); }
    if scope.bid_portal_type != "procontract" { return Err(BidScopeValidationError::UnsupportedPortalType(scope.bid_portal_type.clone())); }

    // FK + ownership
    if !runtime.db.process_exists(&scope.process_id).await? {
        return Err(BidScopeValidationError::ProcessNotFound);
    }
    for lot_id in &scope.lot_ids {
        if !runtime.db.lot_belongs_to_process(lot_id, &scope.process_id).await? {
            return Err(BidScopeValidationError::LotNotOwnedByProcess { lot: lot_id.clone() });
        }
    }
    for cand_id in &scope.candidate_ids {
        if !runtime.db.candidate_belongs_to_lots(cand_id, &scope.lot_ids).await? {
            return Err(BidScopeValidationError::CandidateNotOwnedByLots { candidate: cand_id.clone() });
        }
    }
    for quote_id in &scope.selected_quote_ids {
        if !runtime.db.quote_belongs_to_candidates(quote_id, &scope.candidate_ids).await? {
            return Err(BidScopeValidationError::QuoteNotOwnedByCandidates { quote: quote_id.clone() });
        }
    }
    if !runtime.db.company_profile_version_exists(&scope.company_profile_version).await? {
        return Err(BidScopeValidationError::CompanyProfileVersionNotFound);
    }
    Ok(())
}

pub fn default_bid_scope_fields() -> (bool /* reviewRequired */, SideEffectClass /* sideEffectCap */) {
    (true, SideEffectClass::RemoteDraft) // Decision 5
}
```

