```rust
#[derive(Debug, Clone, Serialize)]
pub struct ReadinessOutcome {
    pub eligible: bool,
    pub blockers: Vec<BidReadinessBlocker>,
    pub resolved_company_profile: Option<CompanyProfile>,  // pre-fetched for runner injection
}

#[derive(Debug, Clone, Serialize)]
pub struct BidReadinessBlocker {
    pub code: String,
    pub source: String,
    pub overrideable: bool,
    pub diagnostic: String,
}

pub async fn evaluate_bid_readiness(
    runtime: &DaemonRuntime,
    scope: &BidScopePayload,
) -> Result<ReadinessOutcome> {
    let mut blockers = vec![];

    // Gate 1: operator approval (non-overrideable)
    let head = runtime.db.load_operator_decision_head(&scope.process_id).await?;
    if head.disposition != "approved" {
        blockers.push(BidReadinessBlocker {
            code: "OPERATOR_NOT_APPROVED".into(),
            source: "operator_decision_heads".into(),
            overrideable: false,
            diagnostic: format!("disposition is {}, need 'approved'", head.disposition),
        });
    }

    // Gate 2: decisionBasisHash freshness (non-overrideable)
    let current_hash = decision_basis_hash::compute(runtime, scope).await?;
    if current_hash != head.reviewed_basis_hash {
        blockers.push(BidReadinessBlocker {
            code: "DECISION_BASIS_STALE".into(),
            source: "operator_decision_heads.reviewedBasisHash".into(),
            overrideable: false,
            diagnostic: format!("operator approved basis {} but current basis is {}",
                                head.reviewed_basis_hash, current_hash),
        });
    }

    // Gate 3: L5 hard blockers (non-overrideable) — wrap existing checks
    for cand_id in &scope.candidate_ids {
        let lce = runtime.db.load_landed_cost_estimate(cand_id).await?;
        // existing L5 raw checks at main.rs:5256-5260 etc.
        if lce.has_classification_ambiguous() {
            blockers.push(blocker("CLASSIFICATION_AMBIGUOUS", "landed_cost_estimates", false, cand_id));
        }
        if lce.has_tariff_branch_divergence() {
            blockers.push(blocker("TARIFF_BRANCH_DIVERGENCE", "landed_cost_estimates", false, cand_id));
        }
        if lce.has_supplementary_unit_missing_required() {
            blockers.push(blocker("SUPPLEMENTARY_UNIT_MISSING", "landed_cost_estimates", false, cand_id));
        }
        if lce.decision_grade == "broker_required" {
            blockers.push(blocker("BROKER_REQUIRED", "landed_cost_estimates", false, cand_id));
        }
        // Gate 4: classification freshness
        if lce.classification_fresh_until_expired() {
            blockers.push(blocker("CLASSIFICATION_FRESH_UNTIL_EXPIRED", "landed_cost_estimates", false, cand_id));
        }
    }

    // Gate 5: company profile currency (non-overrideable)
    let profile_opt = runtime.db.load_company_profile(&scope.company_profile_version).await?;
    let profile = match profile_opt {
        Some(p) if p.has_current_certifications_and_insurance() => Some(p),
        _ => {
            blockers.push(BidReadinessBlocker {
                code: "COMPANY_PROFILE_OUT_OF_DATE".into(),
                source: "shared_company_profile".into(),
                overrideable: false,
                diagnostic: "company profile missing/expired/mismatched version".into(),
            });
            None
        }
    };

    // Gate 6: quote-role quality (overrideable)
    let quote_roles = runtime.db.load_quote_roles(&scope.selected_quote_ids).await?;
    let floor_only = quote_roles.iter().all(|r| r == "domestic_wholesale_floor" || r == "optimistic_floor");
    if floor_only {
        let override_rec = runtime.db.load_quote_role_override(&scope.process_id).await?;
        if override_rec.is_none() || !override_rec.unwrap().valid() {
            blockers.push(BidReadinessBlocker {
                code: "QUOTE_ROLE_FLOOR_ONLY".into(),
                source: "supplier_quotes.price_signal_role".into(),
                overrideable: true,
                diagnostic: "evidence is floor-only; operator structured override required".into(),
            });
        }
    }

    // Gate 7: upstream trust state (trust-debt acceptance only)
    let pa = runtime.db.load_pipeline_assessment(&scope.process_id).await?;
    if pa.validation_state != "validated" {
        let trust_debt = runtime.db.load_trust_debt_acceptance(&scope.process_id, &scope.lot_ids, &scope.candidate_ids).await?;
        if !trust_debt.is_scope_matched() {
            blockers.push(BidReadinessBlocker {
                code: "UPSTREAM_TRUST_UNVALIDATED".into(),
                source: "pipeline_assessments.validation_state".into(),
                overrideable: false,
                diagnostic: format!("validation_state={}, no scope-matched trust-debt acceptance", pa.validation_state),
            });
        }
    }

    // Gate 8: portalOpportunityRef
    if scope.portal_opportunity_ref.is_empty() {
        blockers.push(BidReadinessBlocker {
            code: "PORTAL_OPPORTUNITY_REF_MISSING".into(),
            source: "BidScopePayload".into(),
            overrideable: false,
            diagnostic: "portalOpportunityRef required and non-empty".into(),
        });
    }

    let eligible = blockers.is_empty();
    Ok(ReadinessOutcome { eligible, blockers, resolved_company_profile: profile })
}
