## Implementation Details

```rust
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Serialize, Deserialize)]
#[serde(rename_all = "SCREAMING_SNAKE_CASE")]
pub enum SideEffectClass {
    ReadOnly = 0,
    RemoteDraft = 1,
    NotificationOrLock = 2,
    LegalDeclaration = 3,
    FormalSubmission = 4,
    FundsCommitted = 5,
}

pub enum CapDecision {
    Allowed,
    SaveDraftAndStop { reason: ErrorCode },
    RouteToPortalStateUnknown { reason: ErrorCode },
}

pub fn enforce_cap(next: SideEffectClass, cap: SideEffectClass) -> CapDecision {
    if next <= cap {
        CapDecision::Allowed
    } else if next == SideEffectClass::NotificationOrLock
        || next == SideEffectClass::LegalDeclaration
        || next == SideEffectClass::FundsCommitted {
        // L6-FR-1.7.6 crash recovery by class — these classes need human reconfirm
        CapDecision::RouteToPortalStateUnknown { reason: ErrorCode::BidSideEffectCapExceeded }
    } else {
        // next > cap but within "saveable" classes
        CapDecision::SaveDraftAndStop { reason: ErrorCode::BidSideEffectCapExceeded }
    }
}
```

