// Mirror existing run_extract_document_structure_job (main.rs:1529) signature:
// async fn (NOT pub; private to main.rs module);
// runtime: &mut RuntimeBootstrap (NOT &DaemonRuntime).
async fn run_bid_workflow_job(
    runtime: &mut RuntimeBootstrap,
    runner: &JobRunner,
    claimed: ClaimedJob,
) -> Result<JobOutcome> {
    // 1. Parse payload
    let payload: BidWorkflowJobPayload = serde_json::from_value(claimed.job.payload_json.clone())?;
    let bid_scope = payload.bid_scope_payload;
    let company_profile = payload.company_profile;
    let bid_documents = payload.bid_documents;

    // 2. Re-verify readiness (caller already pre-checked, but L6-FR-1.3.13: recompute at start)
    let readiness = evaluate_bid_readiness(runtime, &bid_scope).await?;
    if !readiness.eligible {
        return Ok(JobOutcome::ReadinessRegression { blockers: readiness.blockers });
    }

    // 3. Browser resource arbitration (AdmissionPriority::BidAutomation)
    let _browser_slot = runtime.resource_arbiter.acquire_browser_slot(&bid_scope.portal_opportunity_ref).await?;

    // 4. Atomic state transition to bid_in_progress
    state_machine::transition_to(
        runtime,
        &claimed.job,
        &bid_scope,
        BidWorkflowState::BidInProgress,
        TransitionContext::operator_start(),
    ).await?;

    // 5. Build skill input (BidScopePayload + CompanyProfile + BidDocuments + selected quote summaries + portal ref)
    let skill_input = build_bid_skill_input(&bid_scope, &company_profile, &bid_documents, runtime).await?;

    // 6. Spawn PTY session via adapter
    let skill = runtime.skill_registry.get("bid-portal/procontract").unwrap();
    let session = runtime.adapter.spawn_pty_session(&skill, &skill_input).await?;

    // 7. Stream events, capture screenshots per step, enforce side-effect cap per step
    let mut highest_se = SideEffectClass::ReadOnly;
    while let Some(event) = session.next_event().await? {
        if let SessionEvent::StepCheckpoint { step, side_effect_class, screenshot } = event {
            // Persist screenshot
            runtime.artifact_store.persist_screenshot(&session.id, step, screenshot).await?;
            // Enforce cap
            match side_effect_guard::enforce_cap(side_effect_class, bid_scope.side_effect_cap) {
                CapDecision::Allowed => { highest_se = highest_se.max(side_effect_class); }
                CapDecision::SaveDraftAndStop { reason } => {
                    return finalize_bid_run(runtime, &claimed.job, &bid_scope, BidWorkflowState::DraftSaved, reason).await;
                }
                CapDecision::RouteToPortalStateUnknown { reason } => {
                    return finalize_bid_run(runtime, &claimed.job, &bid_scope, BidWorkflowState::PortalStateUnknown, reason).await;
                }
            }
        }
    }

    // 8. Skill result drives final state
    let skill_result = session.final_result().await?;
    let final_state = match skill_result.kind {
        BidSkillResultKind::SubmissionResult(_) => BidWorkflowState::BidSubmitted,
        BidSkillResultKind::DraftSaveResult(_) => BidWorkflowState::DraftSaved,
        BidSkillResultKind::AuthStateStale => return Ok(JobOutcome::SkillError { error_code: ErrorCode::AuthStateStale, .. }),
        BidSkillResultKind::Failure(err) => BidWorkflowState::BidFailed,
    };

    // 9. Atomic final state transition + manifest write
    let outcome = finalize_bid_run(runtime, &claimed.job, &bid_scope, final_state, skill_result).await?;

    // 10. Write hybrid run manifest with L6-specific appendix (sibling bead)
    runtime.manifest_writer.write_with_l6_appendix(&session.id, &bid_scope, &readiness, &highest_se, &skill_result).await?;

    Ok(outcome)
}
```

