import type { BidWorkflow, SubmissionResult, DraftSaveResult, PortalStateVerification } from './bid-scope-types';
import { ProcontractWorkflow } from './procontract-workflow';

export class BidWorkflowRegistryError extends Error {
  constructor(public portalType: string) {
    super(`Unsupported bid portal type: ${portalType}. Currently only 'procontract' is supported.`);
  }
}

const REGISTRY: Map<string, () => BidWorkflow> = new Map([
  ['procontract', () => new ProcontractWorkflow()],
  // Future: ['jaggaer', () => new JaggaerWorkflow()],
]);

export function getWorkflow(portalType: string): BidWorkflow {
  const factory = REGISTRY.get(portalType);
  if (!factory) {
    throw new BidWorkflowRegistryError(portalType);
  }
  return factory();
}

export function listSupportedPortals(): string[] {
  return Array.from(REGISTRY.keys());
}

