```typescript
export interface CompanyProfile {
  companyName: string;
  registrationNumber: string;
  vatNumber?: string;
  address: {
    line1: string;
    line2?: string;
    city: string;
    county?: string;
    postcode: string;
    country: string;
  };
  primaryContact: {
    name: string;
    email: string;
    phone: string;
    role: string;
  };
  certifications: Array<{
    type: string;
    number: string;
    expiryDate: string;     // ISO-8601
    issuingBody: string;
  }>;
  insurancePolicies: Array<{
    type: string;
    provider: string;
    policyNumber: string;
    coverAmountPence: number;
    expiryDate: string;
  }>;
  financialStatements?: {
    lastFiledYear: number;
    companiesHouseRef: string;
  };
  smeStatus?: 'micro' | 'small' | 'medium' | 'large';
  equalityStatement?: string;
  environmentalPolicy?: string;
}

export type CompanyProfileValidationError =
  | { kind: 'missing_required_field'; field: string }
  | { kind: 'cert_expired'; certType: string; expiryDate: string }
  | { kind: 'insurance_expired'; insuranceType: string; expiryDate: string };

export function validateCompanyProfile(profile: CompanyProfile, now: Date): CompanyProfileValidationError[] {
  const errors: CompanyProfileValidationError[] = [];

  // Required fields
  if (!profile.companyName) errors.push({ kind: 'missing_required_field', field: 'companyName' });
  if (!profile.registrationNumber) errors.push({ kind: 'missing_required_field', field: 'registrationNumber' });
  if (!profile.address?.line1) errors.push({ kind: 'missing_required_field', field: 'address.line1' });
  if (!profile.address?.city) errors.push({ kind: 'missing_required_field', field: 'address.city' });
  if (!profile.address?.postcode) errors.push({ kind: 'missing_required_field', field: 'address.postcode' });
  if (!profile.address?.country) errors.push({ kind: 'missing_required_field', field: 'address.country' });
  if (!profile.primaryContact?.name) errors.push({ kind: 'missing_required_field', field: 'primaryContact.name' });
  if (!profile.primaryContact?.email) errors.push({ kind: 'missing_required_field', field: 'primaryContact.email' });
  if (!profile.primaryContact?.phone) errors.push({ kind: 'missing_required_field', field: 'primaryContact.phone' });

  // Certification expiry
  for (const cert of profile.certifications ?? []) {
    if (new Date(cert.expiryDate) < now) {
      errors.push({ kind: 'cert_expired', certType: cert.type, expiryDate: cert.expiryDate });
    }
  }

  // Insurance expiry
  for (const ins of profile.insurancePolicies ?? []) {
    if (new Date(ins.expiryDate) < now) {
      errors.push({ kind: 'insurance_expired', insuranceType: ins.type, expiryDate: ins.expiryDate });
    }
  }

  return errors;
}

export function isCompanyProfileCurrent(profile: CompanyProfile, now: Date = new Date()): boolean {
  return validateCompanyProfile(profile, now).length === 0;
}
```

