import React from 'react';
import { BidWorkflowStatusBadge, BidScopeSummary, BidWorkflowStartButton, DraftSavedReviewPanel } from '@testproject1/ui';
import { useDaemonBridge } from '../lib/daemon-bridge';

export const BidWorkflowTab: React.FC<{ processId: string }> = ({ processId }) => {
  const bridge = useDaemonBridge();
  const [bidState, setBidState] = React.useState(null);
  const [readiness, setReadiness] = React.useState(null);

  React.useEffect(() => {
    bridge.loadBidWorkflowState(processId).then(setBidState);
    bridge.evaluateBidReadiness(processId).then(setReadiness);
  }, [processId, bridge]);

  if (!bidState) return <div>Loading...</div>;

  return (
    <div className="bid-workflow-tab">
      <BidWorkflowStatusBadge state={bidState.bid_state} updatedAt={bidState.updated_at} />
      {bidState.bid_scope_json && <BidScopeSummary scope={bidState.bid_scope_json} viewerMode={false} />}
      {bidState.bid_state === 'not_started' || bidState.bid_state === 'ready_to_bid' ? (
        <BidWorkflowStartButton readiness={readiness} onStart={(scope) => bridge.triggerBidWorkflow({ processId, bidScope: scope })} />
      ) : null}
      {bidState.bid_state === 'draft_saved' ? (
        <DraftSavedReviewPanel state={bidState} onResume={() => bridge.resumeBid(processId)} onSubmitFinal={() => bridge.submitFinal(processId)} />
      ) : null}
      {/* SessionViewer integration lives in sibling bead */}
    </div>
  );
};
