  const [acknowledged, setAcknowledged] = useState(false);

  const submit = async () => {
    if (!reason.trim() || !acknowledged) return;
    await onSubmit({
      kind: 'quote_role_floor_only',
      reason: reason.trim(),
      recorded_by: getCurrentOperatorId(),
      recorded_at: new Date().toISOString(),
    });
  };

  return (
    <form onSubmit={submit}>
      <p>This bid is backed only by floor-only evidence (1688 wholesale floor or Alibaba optimistic floor). Submitting requires explicit operator acknowledgment.</p>
      <textarea required value={reason} onChange={e => setReason(e.target.value)} aria-label="Reason for proceeding (required)" />
      <label>
        <input type="checkbox" checked={acknowledged} onChange={e => setAcknowledged(e.target.checked)} />
        I acknowledge that floor-only evidence carries elevated pricing risk.
      </label>
      <button type="submit" disabled={!reason.trim() || !acknowledged}>Override and proceed</button>
    </form>
  );
};
```

